template:
import React from 'react';

interface ToastProps {
  message: string;
  tone?: 'success' | 'error' | 'info';
}

export function Toast({ message, tone = 'info' }: ToastProps) {
  const color = tone === 'success'
    ? '{{token:colors.accent.success}}'
    : tone === 'error'
    ? '{{token:colors.accent.danger}}'
    : '{{token:colors.accent.primary}}';
  return (
    <div style={{
      background: '{{token:colors.base.surface}}',
      border: `1px solid ${color}`,
      borderRadius: '{{token:spacing.card.borderRadius}}',
      padding: '{{token:spacing.card.padding}}',
      color: '{{token:colors.text.primary}}',
      boxShadow: '0 8px 32px {{token:colors.glass.shadow}}',
      maxWidth: '320px',
    }}>
      <span style={{ color }}>●</span> {message}
    </div>
  );
}
